import { readFileSync } from "node:fs";
import { parentPort, workerData, isMainThread } from "node:worker_threads";
import * as py from "../compat/runtime.js";
import { definitions } from "../migrated/py/games/catalog.js";
import { method } from "../services/local.js";
import { check, sha, encode, now } from "../shared/core.js";
import { gameCode } from "../gateway/catalog.js";

// A fixed, per-game probability model. Selection never reads player balances,
// previous wins, merchant turnover or accumulated RTP. Every selected outcome
// is an unchanged, complete round generated by the original local engine.
export const ROUND_MODEL_VERSION = "complete-round-mixture-v1";
export function createEngine(code: string) {
  return py.call(definitions[code].factory, [
    py.jsonLoads(
      readFileSync(py.sourcePath(`services/${code}/config/${code}.json`)),
    ),
  ]);
}
export const invoke = (game: any, name: string, ...args: any[]) =>
  py.plain(method(game, name, ...args.map(py.from)));
export function modeKey(bet: any) {
  return encode(
    Object.fromEntries(
      [
        "mode",
        "extra",
        "ante",
        "ultra",
        "buy",
        "buy_free",
        "buy_bonus",
        "action",
      ]
        .filter(
          (k) =>
            bet[k] !== undefined &&
            !(["action"].includes(k) && bet[k] === "spin"),
        )
        .map((k) => [k, bet[k]]),
    ),
  );
}
export function commands(
  code: string,
  game: any,
  state: any,
  payload: any,
  index: number,
) {
  const command = { ...payload };
  if (state.phase === "ready") return command;
  if (code === "tower-run-treasure-steps")
    return { action: state.phase === "collect" ? "collect" : "continue" };
  if (Object.hasOwn(py.plain(py.attr(game, "config")), "costs"))
    return { action: "confirm", round_id: state.pending.round_id };
  if (
    ["gates-of-olympus", "sweet-bonanza-pop", "big-bass-bonanza"].includes(code)
  )
    return {
      ...command,
      action: state.phase === "collect" ? "collect" : "spin",
      request_index:
        payload.request_index == null
          ? (state.protocol_index ?? 0) + 1
          : payload.request_index + index,
    };
  delete command.buy_free;
  return command;
}
export function completeRound(
  code: string,
  game: any,
  initial: any,
  payload: any,
  root: string,
  sid: string,
) {
  let state = structuredClone(initial),
    credit = 0,
    debit = 0;
  for (let step = 0; step < 4096; step++) {
    const bet = invoke(
      game,
      "normalize_bet",
      commands(code, game, state, payload, step),
    );
    const out = invoke(
      game,
      "step",
      state,
      bet,
      sha(root + ":" + step),
      String(Number(sid) + step),
    );
    credit += out.credit_minor;
    debit += out.debit_minor;
    check(
      Number.isSafeInteger(credit) && Number.isSafeInteger(debit),
      "AMOUNT_INVALID",
    );
    state = out.state;
    if (state.phase === "ready")
      return {
        seed: root,
        total_credit_minor: credit,
        basis_minor: debit,
        steps: step + 1,
        terminal_state: state,
      };
  }
  throw Error("RTP_UNFINISHED_ROUND");
}
export function extremes(
  code: string,
  game: any,
  initial: any,
  payload: any,
  seed: string,
  sid: string,
  count: number,
) {
  let low: any, high: any;
  for (let i = 0; i < count; i++) {
    const r = completeRound(
      code,
      game,
      initial,
      payload,
      sha(seed + ":candidate:" + i),
      sid,
    );
    check(
      r.basis_minor > 0 && (!low || low.basis_minor === r.basis_minor),
      "RTP_INVALID_DEBIT",
    );
    if (!low || r.total_credit_minor < low.total_credit_minor) low = r;
    if (!high || r.total_credit_minor > high.total_credit_minor) high = r;
  }
  return { low, high };
}
export function selectRound(pair: any, probability: number, seed: string) {
  const roll =
    parseInt(sha(seed + ":selection").slice(0, 13), 16) / 0x10000000000000;
  return roll < probability ? pair.high : pair.low;
}
export function modePayloads(code: string) {
  const list: Record<string, any[]> = {
    "3-billion-vaults": [
      {},
      { extra: true },
      { buy: 0 },
      { buy: 1 },
      { buy: 2 },
    ],
    "fortune-gems2": [{}, { extra: true }],
    "jokers-fortune-winx": [{}, { extra: true }],
    "money-pot-deluxe": [0, 1, 2, 3].map((extra) => ({ extra })),
    "roma-x-10000": [{}, { buy: 0 }, { buy: 1 }],
    "super-ace": [{}, { buy_bonus: true }],
    "gates-of-olympus": [{}, { ante: true }, { action: "buy" }],
    "tower-run-treasure-steps": [
      { denom: 10, ultra: false },
      { denom: 10, ultra: true },
    ],
  };
  const cfg = py.plain(py.attr(createEngine(code), "config"));
  if (cfg.costs)
    return Object.keys(cfg.costs).map((mode) => ({
      bet_minor: cfg.default_bet_minor,
      mode,
    }));
  return list[code] ?? [{}];
}
function stats(sum: number, squares: number, n: number) {
  const rtp = sum / n,
    variance = Math.max(0, (squares - (sum * sum) / n) / (n - 1));
  const ci_half = 2.576 * Math.sqrt(variance / n);
  return {
    rounds: n,
    sum,
    squares,
    rtp,
    variance,
    ci_half,
    ci_low: rtp - ci_half,
    ci_high: rtp + ci_half,
    confidence: 0.99,
    unfinished_rounds: 0,
  };
}
export function calibrateRoundModel(
  gameId: number,
  target: number,
  progress = (_v: any) => {},
) {
  const code = gameCode(gameId),
    game = createEngine(code),
    started = Date.now(),
    modes: any = {};
  check(
    gameId !== 1 &&
      Number.isInteger(target) &&
      target >= 8000 &&
      target <= 9900,
    "RTP_TARGET_INVALID",
  );
  const initial = invoke(game, "initial_state", "calibration"),
    wanted = target / 10000;
  for (const payload of modePayloads(code)) {
    const bet = invoke(game, "normalize_bet", payload),
      key = modeKey(bet),
      prefix = `${ROUND_MODEL_VERSION}:${code}:${target}:${key}`;
    let fit: any;
    for (const count of [2, 4, 8, 16]) {
      let low = 0,
        high = 0,
        lo2 = 0,
        hi2 = 0,
        cross = 0;
      const n = 10000;
      for (let i = 0; i < n; i++) {
        const pair = extremes(
          code,
          game,
          initial,
          payload,
          sha(prefix + ":train:" + i),
          "100000",
          count,
        );
        const a = pair.low.total_credit_minor / pair.low.basis_minor,
          b = pair.high.total_credit_minor / pair.high.basis_minor;
        low += a;
        high += b;
        lo2 += a * a;
        hi2 += b * b;
        cross += a * b;
        if (i % 100 === 0)
          progress({
            mode: key,
            stage: "search",
            candidates: count,
            done: i / n,
          });
      }
      if (low / n <= wanted && wanted <= high / n && high > low) {
        const probability = (wanted - low / n) / ((high - low) / n);
        const variance = Math.max(
          0,
          ((1 - probability) ** 2 * lo2 +
            2 * probability * (1 - probability) * cross +
            probability ** 2 * hi2) /
            n -
            wanted * wanted,
        );
        fit = {
          candidates: count,
          upper_probability: probability,
          training: { rounds: n, low_rtp: low / n, high_rtp: high / n },
          variance,
        };
        break;
      }
    }
    check(
      fit,
      "RTP_CALIBRATION_FAILED",
      "Target not bracketed by complete legal rounds",
    );
    // Validation size is chosen from training, before independent holdout data.
    const n =
      Math.ceil(
        Math.max(
          20000,
          Math.min(
            2000000,
            Math.ceil((2.576 ** 2 * fit.variance) / 0.008 ** 2),
          ),
        ) / 100,
      ) * 100;
    const attempts: any[] = [];
    for (let attempt = 0; attempt < 4; attempt++) {
      let sum = 0,
        squares = 0,
        realized = 0,
        block = 0,
        blockSum = 0,
        blockSquares = 0,
        current = structuredClone(initial);
      for (let i = 0; i < n; i++) {
        const seed = sha(prefix + ":holdout:" + attempt + ":" + i),
          pair = extremes(
            code,
            game,
            current,
            payload,
            seed,
            String(100000 + i * 4096),
            fit.candidates,
          );
        const r = selectRound(pair, fit.upper_probability, seed);
        // Integrate the independent selection coin analytically (Rao–Blackwell).
        // Actual selected rounds still advance state. Non-overlapping batches
        // estimate uncertainty with carry-over state instead of treating spins
        // within a feature as independent observations.
        const value =
          ((1 - fit.upper_probability) * pair.low.total_credit_minor +
            fit.upper_probability * pair.high.total_credit_minor) /
          r.basis_minor;
        current = r.terminal_state;
        realized += r.total_credit_minor / r.basis_minor;
        sum += value;
        squares += value * value;
        block += value;
        if (i % 100 === 99) {
          blockSum += block / 100;
          blockSquares += (block / 100) ** 2;
          block = 0;
        }
        if (i % 100 === 0)
          progress({
            mode: key,
            stage: "validation",
            attempt: attempt + 1,
            rounds: n,
            done: i / n,
          });
      }
      const batches = stats(blockSum, blockSquares, n / 100),
        v = {
          ...stats(sum, squares, n),
          variance: batches.variance * 100,
          ci_half: batches.ci_half,
          ci_low: batches.ci_low,
          ci_high: batches.ci_high,
          realized_rtp: realized / n,
          estimator: "conditional expectation with 100-round batch means",
          batch_size: 100,
          batch_sum: blockSum,
          batch_squares: blockSquares,
        },
        passed =
          v.ci_low <= wanted && wanted <= v.ci_high && v.ci_half <= 0.015;
      attempts.push({
        upper_probability: fit.upper_probability,
        validation: v,
        passed,
      });
      if (passed) {
        modes[key] = {
          payload,
          candidates: fit.candidates,
          upper_probability: fit.upper_probability,
          training: fit.training,
          validation: v,
          attempts,
        };
        break;
      }
      fit.upper_probability = Math.max(
        0,
        Math.min(
          1,
          fit.upper_probability +
            (wanted - v.rtp) / (fit.training.high_rtp - fit.training.low_rtp),
        ),
      );
    }
    check(
      modes[key],
      "RTP_CALIBRATION_FAILED",
      "Independent holdout validation failed",
    );
  }
  return {
    format: 2,
    algorithm: ROUND_MODEL_VERSION,
    game_id: gameId,
    engine_version: py.attr(game, "version"),
    ruleset_id: py.attr(game, "ruleset_id"),
    target_bp: target,
    method:
      "fixed probability mixture of complete engine-generated rounds; independent conditional-expectation holdout; 100-round batch means; 99% normal approximation; no turnover feedback",
    certified_theoretical: false,
    created_at: now(),
    seconds: (Date.now() - started) / 1000,
    modes,
    model_hash: sha(encode(modes)),
  };
}
if (!isMainThread && workerData?.roundModel) {
  try {
    parentPort!.postMessage({
      result: calibrateRoundModel(workerData.gameId, workerData.target, (v) =>
        parentPort!.postMessage({ progress: v }),
      ),
    });
  } catch (e) {
    parentPort!.postMessage({
      error: e instanceof Error ? e.message : String(e),
    });
  }
}
